ValidationRule.errorConditionFormula:
AND(
    /* 1. Global Switch Check */
    NOT($Setup.RES_Config_Switch__c.RES_Validation_Rules_Off__c),

    /* 2. Rule only runs on Update, not on Insert */
    NOT(ISNEW()),

    /* 3. Target specific Lead Record Types */
    OR(
        $RecordType.DeveloperName = "RES_Company",
        $RecordType.DeveloperName = "RES_Individual"
    ),

    /* 4. Trigger only if Status is CHANGED to one of the target values */
    ISCHANGED(Status),
    OR(
        ISPICKVAL(Status, "02"),        
        ISPICKVAL(Status, "Converted"),  
        ISPICKVAL(Status, "04")         
    ),

    /* 5. Condition: Project field is missing */
    ISBLANK(TEXT(RES_Project__c))
)
